'use strict';
let LocaleData={exact:{},teams:{},teamIds:{},countries:{},players:{},playerNames:{},competitions:{},countryCodes:{},flags:{},crestHistory:{}};
function localeKey(s){return String(s||'').normalize('NFKD').toLowerCase().replace(/[\u0300-\u036f]/g,'').normalize('NFC').replace(/\b(fc|cf|afc|ac|as|ss|ssc|sc|sv|fk|club|football|calcio|societa|sportiva|spa|sad|srl)\b/g,' ').replace(/[^a-z0-9가-힣]/g,'')}
function koreanName(s){if(s===undefined||s===null)return '';const raw=String(s),rec=LocaleData.teams?.[localeKey(raw)];let direct=LocaleData.exact?.[raw]||LocaleData.countries?.[raw]||rec?.ko;if(direct)return direct;if(typeof names!=='undefined'&&names[raw])return names[raw];let sub=raw.match(/^(.*?)\s+(?:U[- ]?(\d{2})|Under[- ]?(\d{2})|II|B|Reserves)$/i);if(sub){let base=koreanName(sub[1]);if(base!==sub[1])return base+(sub[2]||sub[3]?' U-'+(sub[2]||sub[3]):' 2군')}return raw}
function koreanPlayer(p){return p?.alias||LocaleData.players?.[String(p?.id)]||LocaleData.playerNames?.[p?.name]||p?.name||''}
function koreanPerson(s){return LocaleData.playerNames?.[s]||s}
function koreanCompetition(value){const c=LocaleData.competitions?.[value];if(c?.ko)return c.ko;if(c?.name&&LocaleData.competitions?.[c.name]?.ko)return LocaleData.competitions[c.name].ko;for(let row of Object.values(LocaleData.competitions||{}))if(row.name===value&&row.ko)return row.ko;return value}
function crestRecord(name,id){let keyed=LocaleData.teams?.[localeKey(name)];if(!keyed&&/[가-힣]/.test(name)){let candidates=Object.values(LocaleData.teams||{}).filter(r=>r.ko===name&&r.crest);if(new Set(candidates.map(r=>r.crest)).size===1)keyed=candidates[0]}const explicit=id?LocaleData.teamIds?.[String(id)]:null;const rec=explicit||keyed;if(rec?.crest)return {...rec,type:'crest'};let code=LocaleData.countryCodes?.[name],flag=code&&LocaleData.flags?.[code];return flag?{crest:flag,type:'flag'}:{}}
function crestHTML(name,options={}){let rec=crestRecord(name,options.id);const date=options.date||(typeof state!=='undefined'?state.date:''),history=LocaleData.crestHistory?.[String(options.id||rec.id)]||[],period=history.find(p=>p.from<=date&&p.to>=date);if(period)rec={...rec,...period,type:'historical-crest'};const label=koreanName(name),text=label.replace(/\s/g,'').slice(0,2),size=options.size||'small',title=rec.type==='flag'?'국가 표식 · 현재 국기':rec.type==='historical-crest'?'시대별 엠블럼 · '+rec.period+' · '+rec.evidence:'현재 엠블럼 · 이 날짜의 디자인은 미확인';return `<span class="crest-wrap crest-${size} ${rec.type==='flag'?'crest-flag':''} ${rec.crest?'has-crest':''}" title="${esc(rec.crest?title:'엠블럼 미수록 · 식별용 이니셜')}">${rec.crest?`<img class="crest-image" src="${esc(rec.crest)}" alt="${esc(label)} ${rec.type==='flag'?'국기':rec.type==='historical-crest'?'당시 엠블럼':'현재 엠블럼'}" loading="lazy" decoding="async">`:''}<span class="crest-fallback" aria-hidden="true">${esc(text||'?')}</span></span>`}
function teamLabel(name,options={}){return `<span class="team-identity ${options.reverse?'team-reverse':''}" title="${esc(name)}">${crestHTML(name,options)}<span class="team-name">${esc(koreanName(name))}</span></span>`}
// Failed image requests retain a readable, explicitly non-emblem fallback.
document.addEventListener('error',e=>{if(e.target?.classList?.contains('crest-image')){e.target.parentElement.classList.remove('has-crest');e.target.parentElement.title='엠블럼을 불러오지 못했습니다 · 식별용 이니셜';e.target.remove()}},true);
